// quiz-ui.js
modules[2] = (() => {
// Self-test form shared by the chapters: multiple-choice and numeric questions,
// "New values" regeneration, and worked solutions when the answers are checked.
const $ = id => document.getElementById(id);

function renderQuestion(q, i) {
  const body = q.type === 'mc'
    ? `<div class="quiz-options">${q.options.map((o, j) => `<label class="quiz-option"><input type="radio" name="q${i}" value="${j}"><span>${o}</span></label>`).join('')}</div>`
    : `<div class="quiz-numeric"><label><span class="sr-only">Answer</span><input type="text" inputmode="decimal" name="q${i}" autocomplete="off" placeholder="${q.placeholder ?? 'number'}"></label><span class="unit">${q.unit ?? ''}</span><button type="button" class="quiet-button" data-new="${i}">New values ↻</button></div>`;
  return `<fieldset class="quiz-question" id="qq-${i}"><legend><span>${String(i + 1).padStart(2, '0')}</span>${q.prompt}</legend><p class="quiz-ref">${q.ref}</p>${body}<div class="quiz-feedback" id="feedback-${i}"></div></fieldset>`;
}

function parseAnswer(raw, q) {
  const s = String(raw).trim().replace(',', '.').replace('−', '-');
  if (q.time) { const m = s.match(/^(\d{1,2})[:h](\d{2})$/); if (m) return Number(m[1]) + Number(m[2]) / 60; }
  const v = Number(s.replace(/[°a-z\s]/gi, '')); return s === '' || !Number.isFinite(v) ? null : v;
}

/** Mounts the questions into #quiz-questions and wires #quiz-form, #quiz-score and #reset-quiz. */
function mountQuiz(questions) {
  const drawButtons = () => { for (const b of document.querySelectorAll('[data-new]')) b.onclick = () => { const i = Number(b.dataset.new); questions[i].regenerate(); $(`qq-${i}`).outerHTML = renderQuestion(questions[i], i); drawButtons(); }; };
  $('quiz-questions').innerHTML = questions.map(renderQuestion).join(''); drawButtons();
  $('quiz-form').addEventListener('submit', e => {
    e.preventDefault(); let score = 0, answered = 0;
    questions.forEach((q, i) => {
      const fb = $(`feedback-${i}`); let ok = false, given = null;
      if (q.type === 'mc') { const sel = document.querySelector(`input[name="q${i}"]:checked`); if (sel) { given = Number(sel.value); ok = given === q.correct; } }
      else { const v = parseAnswer(document.querySelector(`input[name="q${i}"]`).value, q); if (v !== null) { given = v; ok = Math.abs((q.time ? ((v - q.answer + 36) % 24) - 12 : v - q.answer)) <= q.tolerance; } }
      if (given !== null) answered++; if (ok) score++;
      fb.className = `quiz-feedback ${given === null ? 'empty' : ok ? 'correct' : 'incorrect'}`;
      fb.innerHTML = given === null ? '<p>No answer.</p>' : `<p><strong>${ok ? 'Correct.' : 'Not correct.'}</strong>${q.type === 'num' ? ` Answer: ${q.answerText}.` : ''}</p>${q.solution}`;
    });
    $('quiz-score').textContent = `${score} / ${questions.length} correct${answered < questions.length ? ` · ${questions.length - answered} unanswered` : ''}`;
  });
  $('reset-quiz').addEventListener('click', () => { $('quiz-form').reset(); for (const el of document.querySelectorAll('.quiz-feedback')) { el.innerHTML = ''; el.className = 'quiz-feedback'; } $('quiz-score').textContent = ''; });
}

return { parseAnswer, mountQuiz };
})();

// nav.js
modules[3] = (() => {
// Sidebar navigation shared by the chapters: mobile menu, active section and reading progress.
const $ = id => document.getElementById(id);

function mountNav() {
  const menu = $('menu-toggle'), sidebar = $('sidebar'), mobile = window.matchMedia('(max-width:900px)');
  const syncNav = () => { sidebar.inert = mobile.matches && menu.getAttribute('aria-expanded') !== 'true'; };
  const closeMenu = () => { sidebar.classList.remove('open'); menu.setAttribute('aria-expanded', 'false'); syncNav(); };
  menu.addEventListener('click', () => { const open = menu.getAttribute('aria-expanded') !== 'true'; menu.setAttribute('aria-expanded', String(open)); sidebar.classList.toggle('open', open); syncNav(); });
  document.addEventListener('keydown', e => { if (e.key === 'Escape') { const was = menu.getAttribute('aria-expanded') === 'true'; closeMenu(); if (was && mobile.matches) menu.focus(); } });
  mobile.addEventListener('change', () => { closeMenu(); syncNav(); }); syncNav();
  document.addEventListener('click', e => { if (!sidebar.contains(e.target) && !menu.contains(e.target)) closeMenu(); });
  for (const link of sidebar.querySelectorAll('a')) link.addEventListener('click', closeMenu);
  const navLinks = [...sidebar.querySelectorAll('nav a')], sections = navLinks.map(a => document.querySelector(a.getAttribute('href')));
  let scrollScheduled = false;
  function updateReading() {
    const max = document.documentElement.scrollHeight - window.innerHeight, pct = Math.min(100, Math.max(0, max > 0 ? Math.round(window.scrollY / max * 100) : 0));
    $('progress-number').textContent = `${pct}%`; $('reading-progress').style.width = `${pct}%`;
    let current = sections[0]; for (const s of sections) if (s.getBoundingClientRect().top < window.innerHeight * .35) current = s;
    for (const l of navLinks) { const on = l.hash === `#${current.id}`; l.classList.toggle('active', on); if (on) l.setAttribute('aria-current', 'location'); else l.removeAttribute('aria-current'); }
    scrollScheduled = false;
  }
  window.addEventListener('scroll', () => { if (!scrollScheduled) { scrollScheduled = true; requestAnimationFrame(updateReading); } }, { passive: true });
  window.addEventListener('resize', updateReading);
  updateReading();
}

return { mountNav };
})();

// diagram-scale.js
modules[4] = (() => {
// Each figure is drawn in its own viewBox and stretched to its column, so one drawing unit
// becomes anything from 0.3 to 1.7 screen pixels. Strokes are drawn non-scaling (solar.css);
// this sets --u (drawing units per screen pixel) on every diagram so its text, sized by --fs,
// shows at the same pixel size in every figure. Text never grows past its size in drawing
// units, since labels are laid out at that size: in figures shown below 1:1 it shrinks with them.
const U_MIN = .5, U_MAX = 1;

function fitDiagramText(root = document.body) {
  if (typeof ResizeObserver === 'undefined') return;
  const resize = new ResizeObserver(entries => {
    for (const { target } of entries) {
      const vb = target.viewBox?.baseVal, w = target.getBoundingClientRect().width;
      if (vb?.width && w) target.style.setProperty('--u', Math.min(U_MAX, Math.max(U_MIN, vb.width / w)).toFixed(3));
    }
  });
  const watch = node => {
    if (node.nodeType !== 1) return;
    if (node.matches('svg.diagram')) resize.observe(node);
    node.querySelectorAll('svg.diagram').forEach(svg => resize.observe(svg));
  };
  watch(root);
  // Interactive diagrams are redrawn as new SVG elements.
  new MutationObserver(records => records.forEach(r => r.addedNodes.forEach(watch))).observe(root, { childList: true, subtree: true });
}

return { fitDiagramText };
})();

